<section class="sf38-card sf39-week-plan" aria-label="Lịch tập tuần này">
    <div class="arena-week"><div class="arena-week-head"><strong>Lịch đăng ký tuần này</strong><a href="<?= sf_h(url('profile?section=schedule')) ?>">Quản lý lịch ↗</a></div><div class="arena-days"><?php $arenaPlanMap = array_column($plansCurrent, 'planned_time', 'planned_date'); $arenaMonday = new DateTimeImmutable($currentWeek); for ($arenaDay = 0; $arenaDay < 7; $arenaDay++): $arenaDate = $arenaMonday->modify('+' . $arenaDay . ' days'); $arenaDateKey = $arenaDate->format('Y-m-d'); $arenaHasPlan = array_key_exists($arenaDateKey, $arenaPlanMap); ?><div class="<?= $arenaHasPlan ? 'is-planned' : '' ?>"><small><?= ['T2','T3','T4','T5','T6','T7','CN'][$arenaDay] ?></small><b><?= $arenaDate->format('d') ?></b><span><?= $arenaHasPlan ? sf_h(substr((string)$arenaPlanMap[$arenaDateKey], 0, 5)) : '—' ?></span></div><?php endfor; ?></div></div>
